parameters.jsCode:
const esEvento = $('🔔 Webhook: Marcar Evento').isExecuted;

let companyId, modo, descripcion;
if (esEvento) {
  const body = $('🔔 Webhook: Marcar Evento').first().json.body || {};
  companyId = Number(body.company_id);
  descripcion = String(body.descripcion || 'Evento sin descripción').trim();
  modo = 'linea_base_evento';
} else {
  companyId = Number($('⚙️ Config G54').item.json.G54_COMPANY_ID);
  descripcion = '';
  modo = 'linea_base';
}

const metricas = $('📊 Línea Base: Métricas').first().json;
const leads = $('📊 Línea Base: Leads').first().json;
const crm = $('📊 Línea Base: CRM').first().json;

// Con onError:continueRegularOutput en el nodo, si la llamada falla este item
// llega vacío ({}) — nunca rompe la captura de la línea base por faltar el nombre.
const empRaw = $('🏢 Línea Base: Obtener Empresa').first().json || {};
const emp = empRaw.data || empRaw || {};
const companyName = emp.name || '';
const city = emp.base_city || '';

function sumMetric(rows, campo) {
  if (!Array.isArray(rows)) return 0;
  return rows.reduce((acc, r) => acc + (Number(r[campo]) || 0), 0);
}

const metricasRows = (metricas && metricas.data) || [];
const alcance = sumMetric(metricasRows, 'alcance_total');
const engagement = sumMetric(metricasRows, 'engagement_total');
const leadsMetricas = sumMetric(metricasRows, 'leads_total');

// Mismo criterio que las métricas de arriba (ventana de 30 días) — la lectura de
// "hoy" en Analytics V3 cuenta leads del período (últimos 30 días), no el total
// histórico de conversaciones. Sin este filtro, la línea base comparaba un total
// acumulado de siempre contra un número acotado al período, dos cosas distintas.
const hace30dias = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);
const leadsArr = ((leads && leads.data) || []).filter(c => c.created_at && new Date(c.created_at) >= hace30dias);
const totalLeadsConversaciones = leadsArr.length;

let deals = 0;
let ventasCerradas = 0;
// "Negocios en el CRM" = pipeline activo real, nunca lost ni closed — mismo criterio
// que la lectura de "hoy" en Analytics V3, para que la línea base y la comparación
// futura midan siempre lo mismo. lost es basura acumulada sin forma de borrarse hoy.
const ETAPAS_ACTIVAS = ['new', 'qualifying', 'proposal', 'negotiation'];
if (crm && typeof crm === 'object') {
  for (const [etapa, v] of Object.entries(crm)) {
    if (!Array.isArray(v)) continue;
    if (ETAPAS_ACTIVAS.includes(etapa)) deals += v.length;
    if (etapa === 'closed') {
      ventasCerradas += v.reduce((acc, d) => acc + (Number(d.valor_estimado) || 0), 0);
    }
  }
}

const fecha = new Date().toISOString().slice(0, 10);
const fechaLegible = new Date(fecha + 'T12:00:00').toLocaleDateString('es-NI', { day: 'numeric', month: 'long', year: 'numeric' });
const titulo = modo === 'linea_base_evento'
  ? ('Evento — ' + descripcion + ' — ' + fecha)
  : ('Línea base — ' + fecha);

const baseline = {
  fecha,
  company_id: companyId,
  descripcion,
  alcance_total: alcance,
  engagement_total: engagement,
  leads_total_metricas: leadsMetricas,
  leads_total_conversaciones: totalLeadsConversaciones,
  deals_total: deals,
  ventas_cerradas: ventasCerradas,
};

// Mismo header/logo que ya usa el reporte real de Analytics V3 — reusado tal cual,
// no un estilo nuevo. Solo cambia el eyebrow y el contenido del cuerpo.
const eyebrow = modo === 'linea_base_evento'
  ? 'EVENTO MARCADO · MÓDULO 1 — RRSS'
  : 'PUNTO DE PARTIDA DE LA ESTRATEGIA · MÓDULO 1 — RRSS';

const descripcionTexto = modo === 'linea_base_evento'
  ? ('Referencia marcada a mano para medir el antes/después de un cambio puntual: <strong>' + descripcion + '</strong>.')
  : 'Foto del estado real de la cuenta al iniciar (o regenerar) la estrategia. Sirve como punto de comparación para medir el progreso real en los reportes periódicos.';

function statCard(icon, val, label) {
  return `<table width="100%" cellpadding="0" cellspacing="0" style="background:#fff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden;"><tr><td width="4" style="background:#2D5BFF;border-radius:10px 0 0 10px;font-size:0;">&nbsp;</td><td style="padding:12px 12px 10px;"><div style="font-size:15px;margin-bottom:3px;">${icon}</div><div style="font-size:20px;font-weight:800;color:#111827;line-height:1;">${val}</div><div style="font-size:9px;color:#9ca3af;margin-top:7px;text-transform:uppercase;letter-spacing:.05em;">${label}</div></td></tr></table>`;
}
function statsRow(c1, c2, c3) {
  return `<table width="100%" cellpadding="0" cellspacing="0"><tr><td width="32%">${c1}</td><td width="2%">&nbsp;</td><td width="32%">${c2}</td><td width="2%">&nbsp;</td><td width="32%">${c3}</td></tr></table>`;
}

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${titulo}</title></head>
<body style="margin:0;padding:32px 16px;background:#eef0f4;font-family:Arial,'Helvetica Neue',sans-serif;">
<table width="600" cellpadding="0" cellspacing="0" style="margin:0 auto;">
<tr><td style="background:linear-gradient(135deg,#2D5BFF 0%,#1E45D6 100%);border-radius:12px 12px 0 0;padding:26px 28px 24px;">
  <table width="100%" cellpadding="0" cellspacing="0"><tr><td>
    <table cellpadding="0" cellspacing="0"><tr>
      <td style="vertical-align:middle;"><span style="font-size:20px;font-weight:600;color:#fff;letter-spacing:-0.3px;font-family:Arial,sans-serif;">Growth</span></td>
      <td style="vertical-align:middle;padding:0 1px;"><div style="width:25px;height:25px;background:#fff;border-radius:50%;text-align:center;line-height:25px;color:#2D5BFF;font-size:18px;font-weight:800;letter-spacing:-0.8px;font-family:Arial,sans-serif;display:inline-block;">54</div></td>
      <td style="vertical-align:middle;"><span style="font-size:20px;font-weight:600;color:#fff;letter-spacing:-0.3px;font-family:Arial,sans-serif;">ai</span></td>
    </tr></table>
    <div style="margin-top:18px;font-size:11px;letter-spacing:1.5px;text-transform:uppercase;color:#CFE0FF;font-weight:700;">${eyebrow}</div>
    <div style="font-size:21px;font-weight:600;color:#fff;margin-top:4px;">${companyName}${city ? ` <span style="color:#BFD4FF;font-weight:400;font-size:14px;">— ${city}</span>` : ''}</div>
  </td></tr></table>
  <table cellpadding="0" cellspacing="0" style="margin-top:16px;background:rgba(255,255,255,.14);border:1px solid rgba(255,255,255,.22);border-radius:8px;"><tr>
    <td style="padding:8px 14px;"><span style="display:inline-block;width:8px;height:8px;border-radius:50%;background:#3FD68F;margin-right:8px;">&nbsp;</span><span style="font-size:12.5px;color:#fff;font-weight:600;">${fechaLegible}</span></td>
  </tr></table>
</td></tr>
<tr><td style="background:#fff;border:1px solid #e5e7eb;border-top:none;padding:22px 24px;">
  <p style="font-size:12.5px;color:#64748b;margin:0 0 18px;line-height:1.55;">${descripcionTexto}</p>
  ${statsRow(
    statCard('📣', alcance.toLocaleString('es-NI'), 'Alcance (30 días)'),
    statCard('💬', engagement.toLocaleString('es-NI'), 'Engagement (30 días)'),
    statCard('💎', leadsMetricas.toLocaleString('es-NI'), 'Leads (métricas)')
  )}
  <div style="height:10px;">&nbsp;</div>
  ${statsRow(
    statCard('📱', totalLeadsConversaciones.toLocaleString('es-NI'), 'Conversaciones WA'),
    statCard('🤝', deals.toLocaleString('es-NI'), 'Negocios en CRM'),
    statCard('💰', '$' + ventasCerradas.toLocaleString('es-NI'), 'Ventas cerradas')
  )}
</td></tr>
<tr><td style="background:#fff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 12px 12px;padding:14px 24px;text-align:center;">
  <span style="font-size:10.5px;color:#9ca3af;">Growth54ai — punto de referencia interno para medir progreso, no un resultado del período</span>
</td></tr>
</table>
</body></html>` + `<!-- LINEA_BASE_JSON: ${JSON.stringify(baseline)} -->`;

return [{
  json: {
    company_id: companyId,
    titulo,
    periodo_inicio: fecha,
    periodo_fin: fecha,
    modo,
    html,
    baseline,
  }
}];

// Guarda la línea base en el campo linea_base de la estrategia (G54, 29-sep), no como
// informe: antes quedaba en la lista de Informes que ve el cliente. El campo solo se
// escribe con POST /api/agent/rrss/estrategia, que hace updateOrCreate por empresa, así
// que se reenvía la estrategia vigente completa (probado el 30-sep: ningún campo cambia).
// Formato: { version: 1, inicio: {...}, eventos: [{...}] } — inicio es el punto de
// partida de la estrategia; eventos, los "Marcar evento" posteriores (últimos 20).
const BASE = 'https://apigrowth.mdarthurdigital.com';
const AGENT = 'Bearer <G54_AGENT_TOKEN — ver .secrets.local.md>';
const it = $input.first().json;
const bl = it.baseline;
const companyId = Number(it.company_id);
const SKIP = ['id', 'created_at', 'updated_at', 'generated_at', 'generated_by', 'link_origen', 'link_resuelto', 'linea_base'];

const resp = await this.helpers.httpRequest({
  method: 'GET', url: `${BASE}/api/n8n/companies/${companyId}/rrss/estrategia`,
  headers: { Authorization: AGENT }, json: true,
});
const est = resp && (resp.data || resp);
if (!est || !est.id) {
  return [{ json: { ok: false, motivo: 'La empresa no tiene estrategia: no hay dónde guardar la línea base.', company_id: companyId } }];
}
const prev = (est.linea_base && typeof est.linea_base === 'object' && est.linea_base.version === 1)
  ? est.linea_base : { version: 1, inicio: null, eventos: [] };
let lb;
if (it.modo === 'linea_base_evento') {
  lb = { ...prev, eventos: [...(prev.eventos || []), bl].slice(-20) };
} else {
  // Estrategia nueva: nuevo punto de partida, los eventos de la anterior ya no aplican.
  lb = { version: 1, inicio: bl, eventos: [] };
}
const body = {};
for (const [k, v] of Object.entries(est)) if (!SKIP.includes(k)) body[k] = v;
for (const k of ['fecha_inicio', 'fecha_fin']) if (body[k]) body[k] = String(body[k]).slice(0, 10);
body.company_id = companyId;
body.linea_base = lb;
const r = await this.helpers.httpRequest({
  method: 'POST', url: `${BASE}/api/agent/rrss/estrategia`,
  headers: { Authorization: AGENT, 'Content-Type': 'application/json' }, body, json: true,
});
return [{ json: { ok: !!(r && r.ok), company_id: companyId, modo: it.modo, fecha: bl.fecha } }];
